parameters.jsonBody:
={
  "type": "message",
  "attachments": [
    {
      "contentType": "application/vnd.microsoft.card.adaptive",
      "content": {
        "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
        "type": "AdaptiveCard",
        "version": "1.4",
        "body": [
          {
            "type": "TextBlock",
            "text": "🥚 ESCALA DE COMPRA DE OVOS 🥚",
            "weight": "Bolder",
            "size": "Large",
            "wrap": true
          },
          {
            "type": "TextBlock",
            "text": "📅 Semana atual",
            "weight": "Bolder",
            "spacing": "Medium",
            "wrap": true
          },
          {
            "type": "TextBlock",
            "text": "Início em: {{ $json.draw_date.split('-').reverse().join('/') }}",
            "wrap": true
          },
          {
            "type": "TextBlock",
            "text": "👥 Responsáveis",
            "weight": "Bolder",
            "spacing": "Medium",
            "wrap": true
          },
          {
            "type": "TextBlock",
            "text": "{{ $json.person1_name }} e {{ $json.person2_name }}",
            "wrap": true
          },
          {
            "type": "TextBlock",
            "text": "🛒 Padrão de compra",
            "weight": "Bolder",
            "spacing": "Medium",
            "wrap": true
          },
          {
            "type": "TextBlock",
            "text": "Cada um deve comprar uma cartela com 30 ovos",
            "wrap": true
          },
          {
            "type": "TextBlock",
            "text": "🔁 Ciclo atual: #{{ $json.cycle_number }}",
            "spacing": "Medium",
            "isSubtle": true,
            "wrap": true
          }
        ]
      }
    }
  ]
}
